import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int length = scanner.nextInt();
        scanner.nextLine();
        String inputLine = scanner.nextLine().trim();
        char[] arrayChars = inputLine.toCharArray();

        int[] arrayVals = new int[length];
        for (int i = 0; i < length; i++) {
            arrayVals[i] = scanner.nextInt();
        }
        scanner.nextLine();

        List<CharInfo> mismatchList = new ArrayList<>();
        List<CharInfo> pairList = new ArrayList<>();
        for (int i = 0; i < length / 2; i++) {
            if (arrayVals[i] > arrayVals[length - i - 1]) {
                swap(arrayChars, arrayVals, i);
            }
            CharInfo ci = new CharInfo(arrayChars[i], arrayVals[i], i);
            if (arrayChars[i] == arrayChars[length - i - 1]) {
                mismatchList.add(ci);
            }
            pairList.add(ci);
        }
        pairList.sort(Comparator.comparing(c -> c.value));

        int totalDifference = 0;
        if (!isAntiPalindrome(arrayChars)) {
            if (mismatchList.size() == 1) {
                CharInfo wrongChar = mismatchList.get(0);
                for (CharInfo ci : pairList) {
                    if (ci.chr != wrongChar.chr && arrayChars[length - ci.idx - 1] != wrongChar.chr) {
                        totalDifference = wrongChar.val + ci.val;
                        break;
                    }
                }
            } else if (mismatchList.size() > 1) {
                Map<Character, Integer> countMap = new HashMap<>();
                for (CharInfo ci : mismatchList) {
                    countMap.put(ci.chr, countMap.getOrDefault(ci.chr, 0) + 1);
                }
                int maxCount = Collections.max(countMap.values());
                List<CharInfo> appendList = new ArrayList<>();
                while (maxCount * 2 > mismatchList.size() + appendList.size()) {
                    char maxChar = Collections.max(countMap.entrySet(), Map.Entry.comparingByValue()).getKey();
                    for (CharInfo ci : pairList) {
                        if (ci.chr != maxChar && arrayChars[length - ci.idx - 1] != maxChar && !mismatchList.contains(ci) && !appendList.contains(ci)) {
                            appendList.add(ci);
                            break;
                        }
                    }
                }
                totalDifference = mismatchList.stream().mapToInt(c -> c.val).sum() + appendList.stream().mapToInt(c -> c.val).sum();
            }
        }
        int sumAll = Arrays.stream(arrayVals).sum();
        System.out.println(sumAll - totalDifference);
    }

    private static void swap(char[] chArr, int[] vals, int i) {
        char tempChar = chArr[i];
        chArr[i] = chArr[chArr.length - i - 1];
        chArr[chArr.length - i - 1] = tempChar;

        int tempVal = vals[i];
        vals[i] = vals[vals.length - i - 1];
        vals[vals.length - i - 1] = tempVal;
    }

    private static boolean isAntiPalindrome(char[] chArr) {
        int len = chArr.length;
        for (int i = 0; i < len / 2; i++) {
            if (chArr[i] == chArr[len - i - 1]) {
                return false;
            }
        }
        return true;
    }

    static class CharInfo {
        char chr;
        int val;
        int idx;

        CharInfo(char chr, int val, int idx) {
            this.chr = chr;
            this.val = val;
            this.idx = idx;
        }
    }
}
