def swap(chArr, vals, i):
    chArr[i], chArr[-i-1] = chArr[-i-1], chArr[i]
    vals[i], vals[-i-1] = vals[-i-1], vals[i]

def isAntiPalindrome(chArr):
    length = len(chArr)
    for i in range(length // 2):
        if chArr[i] == chArr[length - i - 1]:
            return False
    return True

mismatchList = []
